CREATE TABLE "${primehrSchema}".evidence_assessment_cycle (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,title VARCHAR(200) NOT NULL,description VARCHAR(2000),framework_version_id VARCHAR(36) NOT NULL,framework_definition_version INTEGER NOT NULL,framework_content_revision INTEGER NOT NULL,framework_fingerprint VARCHAR(64) NOT NULL,period_start DATE NOT NULL,period_end DATE NOT NULL,due_date DATE NOT NULL,status VARCHAR(20) NOT NULL,opened_by VARCHAR(100),opened_at TIMESTAMP WITH TIME ZONE,closed_by VARCHAR(100),closed_at TIMESTAMP WITH TIME ZONE,transition_reason VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_evidence_cycle_framework FOREIGN KEY(framework_version_id) REFERENCES "${primehrSchema}".evidence_framework_version(id),CONSTRAINT uk_evidence_cycle_code UNIQUE(agency_id,normalized_code),CONSTRAINT ck_evidence_cycle_dates CHECK(period_end>=period_start AND due_date>=period_end),CONSTRAINT ck_evidence_cycle_status CHECK(status IN('DRAFT','OPEN','CLOSED','CANCELLED')));
CREATE INDEX ix_evidence_cycle_period ON "${primehrSchema}".evidence_assessment_cycle(agency_id,status,period_start,period_end);
CREATE TABLE "${primehrSchema}".evidence_assessment_case (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,cycle_id VARCHAR(36) NOT NULL,framework_version_id VARCHAR(36) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,title VARCHAR(250) NOT NULL,organization_type VARCHAR(30) NOT NULL,organization_id BIGINT NOT NULL,organization_name VARCHAR(250) NOT NULL,organization_fingerprint VARCHAR(64) NOT NULL,owner_employee_id BIGINT NOT NULL,owner_employee_no VARCHAR(100) NOT NULL,owner_name VARCHAR(250) NOT NULL,owner_appointment_id BIGINT NOT NULL,owner_fingerprint VARCHAR(64) NOT NULL,validator_employee_id BIGINT NOT NULL,validator_employee_no VARCHAR(100) NOT NULL,validator_name VARCHAR(250) NOT NULL,validator_appointment_id BIGINT NOT NULL,validator_fingerprint VARCHAR(64) NOT NULL,validator_recused BOOLEAN NOT NULL DEFAULT FALSE,recusal_reason VARCHAR(2000),status VARCHAR(20) NOT NULL,content_revision INTEGER NOT NULL DEFAULT 0,submission_revision INTEGER NOT NULL DEFAULT 0,submitted_by VARCHAR(100),submitted_at TIMESTAMP WITH TIME ZONE,returned_by VARCHAR(100),returned_at TIMESTAMP WITH TIME ZONE,return_reason VARCHAR(3000),finalized_by VARCHAR(100),finalized_at TIMESTAMP WITH TIME ZONE,finalization_reason VARCHAR(3000),withdrawn_by VARCHAR(100),withdrawn_at TIMESTAMP WITH TIME ZONE,withdrawal_reason VARCHAR(3000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_evidence_case_cycle FOREIGN KEY(cycle_id) REFERENCES "${primehrSchema}".evidence_assessment_cycle(id),CONSTRAINT fk_evidence_case_framework FOREIGN KEY(framework_version_id) REFERENCES "${primehrSchema}".evidence_framework_version(id),CONSTRAINT uk_evidence_case_code UNIQUE(agency_id,cycle_id,normalized_code),CONSTRAINT ck_evidence_case_org CHECK(organization_type IN('AREA','BUSINESS_UNIT')),CONSTRAINT ck_evidence_case_people CHECK(owner_employee_no<>validator_employee_no),CONSTRAINT ck_evidence_case_status CHECK(status IN('DRAFT','SUBMITTED','RETURNED','RESUBMITTED','FINALIZED','WITHDRAWN')),CONSTRAINT ck_evidence_case_revisions CHECK(content_revision>=0 AND submission_revision>=0));
CREATE INDEX ix_evidence_case_assignment ON "${primehrSchema}".evidence_assessment_case(agency_id,status,owner_employee_no,validator_employee_no);
CREATE TABLE "${primehrSchema}".evidence_artifact (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,assessment_case_id VARCHAR(36) NOT NULL,requirement_id VARCHAR(36) NOT NULL,requirement_code VARCHAR(80) NOT NULL,title VARCHAR(250) NOT NULL,notes VARCHAR(3000),kind VARCHAR(20) NOT NULL,source_type VARCHAR(30),source_id VARCHAR(100),source_version BIGINT,source_fingerprint VARCHAR(64),source_label VARCHAR(500),source_changed_at TIMESTAMP WITH TIME ZONE,original_filename VARCHAR(255),storage_provider VARCHAR(30),storage_object_key VARCHAR(500),media_type VARCHAR(120),byte_size BIGINT,checksum VARCHAR(64),classification VARCHAR(20) NOT NULL,visibility VARCHAR(30) NOT NULL,retention_tag VARCHAR(100) NOT NULL,evidence_date DATE NOT NULL,review_due_date DATE,last_verified_at TIMESTAMP WITH TIME ZONE,verification_status VARCHAR(20) NOT NULL,verification_message VARCHAR(1000),supersedes_id VARCHAR(36),current_record BOOLEAN NOT NULL DEFAULT TRUE,added_by VARCHAR(100) NOT NULL,added_at TIMESTAMP WITH TIME ZONE NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_evidence_artifact_case FOREIGN KEY(assessment_case_id) REFERENCES "${primehrSchema}".evidence_assessment_case(id),CONSTRAINT fk_evidence_artifact_req FOREIGN KEY(requirement_id) REFERENCES "${primehrSchema}".evidence_requirement(id),CONSTRAINT fk_evidence_artifact_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".evidence_artifact(id),CONSTRAINT ck_evidence_artifact_kind CHECK(kind IN('LIVE_SOURCE','UPLOAD')),CONSTRAINT ck_evidence_artifact_class CHECK(classification IN('PUBLIC','INTERNAL','CONFIDENTIAL','RESTRICTED')),CONSTRAINT ck_evidence_artifact_visibility CHECK(visibility IN('OWNER_AND_VALIDATOR','VALIDATOR_ONLY','AGENCY_AUTHORIZED')),CONSTRAINT ck_evidence_artifact_verify CHECK(verification_status IN('VERIFIED','STALE','BROKEN','UNVERIFIED')),CONSTRAINT ck_evidence_artifact_date CHECK(review_due_date IS NULL OR review_due_date>=evidence_date),CONSTRAINT ck_evidence_artifact_payload CHECK((kind='LIVE_SOURCE' AND source_type IS NOT NULL AND source_id IS NOT NULL AND source_version IS NOT NULL AND source_fingerprint IS NOT NULL AND storage_object_key IS NULL) OR (kind='UPLOAD' AND storage_object_key IS NOT NULL AND media_type IS NOT NULL AND byte_size>0 AND checksum IS NOT NULL AND source_id IS NULL)));
CREATE INDEX ix_evidence_artifact_case ON "${primehrSchema}".evidence_artifact(agency_id,assessment_case_id,requirement_id,current_record);
CREATE TABLE "${primehrSchema}".evidence_finding (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,assessment_case_id VARCHAR(36) NOT NULL,requirement_id VARCHAR(36) NOT NULL,requirement_code VARCHAR(80) NOT NULL,submission_revision INTEGER NOT NULL,finding_revision INTEGER NOT NULL,supersedes_id VARCHAR(36),current_record BOOLEAN NOT NULL DEFAULT TRUE,outcome VARCHAR(30) NOT NULL,rationale VARCHAR(4000) NOT NULL,not_applicable_authority VARCHAR(1000),decided_by VARCHAR(100) NOT NULL,decided_at TIMESTAMP WITH TIME ZONE NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_evidence_finding_case FOREIGN KEY(assessment_case_id) REFERENCES "${primehrSchema}".evidence_assessment_case(id),CONSTRAINT fk_evidence_finding_req FOREIGN KEY(requirement_id) REFERENCES "${primehrSchema}".evidence_requirement(id),CONSTRAINT fk_evidence_finding_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".evidence_finding(id),CONSTRAINT uk_evidence_finding_revision UNIQUE(agency_id,assessment_case_id,requirement_id,finding_revision),CONSTRAINT ck_evidence_finding_outcome CHECK(outcome IN('MET','PARTIALLY_MET','NOT_MET','NOT_APPLICABLE','NEEDS_REVIEW')),CONSTRAINT ck_evidence_finding_revision CHECK(submission_revision>=1 AND finding_revision>=1),CONSTRAINT ck_evidence_finding_na CHECK(outcome<>'NOT_APPLICABLE' OR not_applicable_authority IS NOT NULL));
CREATE INDEX ix_evidence_finding_case ON "${primehrSchema}".evidence_finding(agency_id,assessment_case_id,requirement_id,current_record);
CREATE TABLE "${primehrSchema}".evidence_gap (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,assessment_case_id VARCHAR(36) NOT NULL,requirement_id VARCHAR(36) NOT NULL,finding_id VARCHAR(36) NOT NULL,reason VARCHAR(3000) NOT NULL,severity VARCHAR(30) NOT NULL,status VARCHAR(20) NOT NULL,opened_by VARCHAR(100) NOT NULL,opened_at TIMESTAMP WITH TIME ZONE NOT NULL,resolved_by VARCHAR(100),resolved_at TIMESTAMP WITH TIME ZONE,resolution_reason VARCHAR(3000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_evidence_gap_case FOREIGN KEY(assessment_case_id) REFERENCES "${primehrSchema}".evidence_assessment_case(id),CONSTRAINT fk_evidence_gap_req FOREIGN KEY(requirement_id) REFERENCES "${primehrSchema}".evidence_requirement(id),CONSTRAINT fk_evidence_gap_finding FOREIGN KEY(finding_id) REFERENCES "${primehrSchema}".evidence_finding(id),CONSTRAINT ck_evidence_gap_status CHECK(status IN('OPEN','RESOLVED','REOPENED')));
CREATE INDEX ix_evidence_gap_case ON "${primehrSchema}".evidence_gap(agency_id,assessment_case_id,status);
CREATE TABLE "${primehrSchema}".evidence_corrective_action (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,gap_id VARCHAR(36) NOT NULL,assessment_case_id VARCHAR(36) NOT NULL,action_plan VARCHAR(3000) NOT NULL,responsible_employee_no VARCHAR(100) NOT NULL,responsible_name VARCHAR(250) NOT NULL,target_date DATE NOT NULL,status VARCHAR(40) NOT NULL,progress_note VARCHAR(3000),completion_evidence_reference VARCHAR(1000),submitted_by VARCHAR(100),submitted_at TIMESTAMP WITH TIME ZONE,verified_by VARCHAR(100),verified_at TIMESTAMP WITH TIME ZONE,decision_reason VARCHAR(3000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_evidence_action_gap FOREIGN KEY(gap_id) REFERENCES "${primehrSchema}".evidence_gap(id),CONSTRAINT fk_evidence_action_case FOREIGN KEY(assessment_case_id) REFERENCES "${primehrSchema}".evidence_assessment_case(id),CONSTRAINT ck_evidence_action_status CHECK(status IN('PLANNED','IN_PROGRESS','SUBMITTED_FOR_VERIFICATION','VERIFIED','RETURNED','CANCELLED')));
CREATE INDEX ix_evidence_action_owner ON "${primehrSchema}".evidence_corrective_action(agency_id,assessment_case_id,responsible_employee_no,status,target_date);
CREATE TABLE "${primehrSchema}".evidence_assessment_event (id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,assessment_case_id VARCHAR(36) NOT NULL,aggregate_type VARCHAR(40) NOT NULL,aggregate_id VARCHAR(36) NOT NULL,event_type VARCHAR(60) NOT NULL,actor_employee_no VARCHAR(100) NOT NULL,reason VARCHAR(3000),from_status VARCHAR(40),to_status VARCHAR(40),event_at TIMESTAMP WITH TIME ZONE NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_evidence_event_case FOREIGN KEY(assessment_case_id) REFERENCES "${primehrSchema}".evidence_assessment_case(id));
CREATE INDEX ix_evidence_event_case ON "${primehrSchema}".evidence_assessment_event(agency_id,assessment_case_id,event_at);
